export const ITEMS={sword_fine:{name:'Закалённый меч',slot:0,weaponClass:'sword',damageMultiplier:1.25,description:'Урон меча +25%'},bow_fine:{name:'Усиленный лук',slot:0,weaponClass:'bow',damageMultiplier:1.25,description:'Урон стрел +25%'},mage_fine:{name:'Рунный посох',slot:0,weaponClass:'mage',damageMultiplier:1.25,description:'Урон заклинаний +25%'},shield:{name:'Деревянный щит',slot:1,description:'ПКМ: блок. 15 выносливости за попадание'},chain_helmet:{name:'Кольчужный шлем',slot:2,color:'#a8b5bf',description:'+15 здоровья, −8% физического урона при ношении'},leather_helmet:{name:'Кожаный шлем',slot:2,color:'#a57b4d',description:'+15 выносливости, +20% скорости её восстановления при ношении'},cloth_hood:{name:'Тканевый капюшон',slot:2,color:'#64648f',description:'+10 магии, −5% расхода магии, +5% скорости её восстановления при ношении'},jug_empty:{name:'Пустой кувшин',atlas:'0% 0%'},jug_water:{name:'Кувшин с водой',atlas:'100% 0%'},mary_ale:{name:'Эль Мэри',atlas:'0% 100%'},sword:{name:'Меч',slot:0,icon:'⚔',color:'#c5d5dd'},bow:{name:'Лук',slot:0,icon:'➶',color:'#b58c50'},mage:{name:'Посох',slot:0,icon:'✦',color:'#ff9952'},arrow:{name:'Стрелы',icon:'➶',color:'#c9c1a5'},carcass:{name:'Туша кролика',icon:'◆',color:'#c68b83'},fang:{name:'Клык волка',icon:'◢',color:'#e8dfbf'}};

// Equipment values are applied only from the six equipment slots.
Object.assign(ITEMS.chain_helmet,{classId:'sword',bonus:{hp:15,physical:.92}});
Object.assign(ITEMS.leather_helmet,{classId:'bow',bonus:{stamina:15,staminaRegen:1.2}});
Object.assign(ITEMS.cloth_hood,{classId:'mage',bonus:{mana:10,manaCost:.95,manaRegen:1.05}});
for(const [classId,prefix,title,color,bonuses] of [
 ['sword','chain','Кольчужный','#a8b5bf',[{hp:10,physical:.96},{hp:5,physical:.98},{stamina:5}]],
 ['bow','leather','Кожаный','#a57b4d',[{hp:5,stamina:8},{stamina:5,physical:.98},{staminaRegen:1.05}]],
 ['mage','cloth','Тканевый','#8780b2',[{hp:5,mana:8},{mana:5,manaCost:.98},{manaRegen:1.05}]]
]) for(const [i,part] of ['chest','legs','boots'].entries()) ITEMS[prefix+'_'+part]={name:title+' комплект: '+['нагрудник','штаны','ботинки'][i],classId,slot:i+3,color,bonus:bonuses[i],description:Object.entries(bonuses[i]).map(([k,v])=>({hp:'Здоровье +'+v,stamina:'Выносливость +'+v,mana:'Магия +'+v,physical:'Физический урон −'+Math.round((1-v)*100)+'%',staminaRegen:'Восстановление выносливости +'+Math.round((v-1)*100)+'%',manaRegen:'Восстановление магии +'+Math.round((v-1)*100)+'%',manaCost:'Расход магии −'+Math.round((1-v)*100)+'%'}[k])).join(', ')};
Object.assign(ITEMS,{
 shield_fine:{name:'Щит троллебойца',classId:'sword',slot:1,color:'#b7c9cf',description:'Блок: 70% физического / 40% магического урона. Удар щитом +25%.'},
 quiver:{name:'Колчан охотника',classId:'bow',slot:1,color:'#ab7c43',description:'25% шанс сохранить стрелу при выстреле или залпе.'},
 grimoire:{name:'Гримуар третьего пламени',classId:'mage',slot:1,color:'#9b70cf',description:'Каждая третья атака магией наносит на 70% больше урона.'},
 witch_relic:{name:'Запечатанное письмо ведьмы',color:'#77d892',description:'Квестовый предмет. Дважды нажмите, чтобы осмотреть. Продолжение истории появится позже.'}
});
export const equipmentClass=id=>ITEMS[id]?.classId||ITEMS[id]?.weaponClass||(['sword','bow','mage'].includes(id)?id:id==='shield'?'sword':null);
export const canEquip=(id,slot,classId)=>!id||slot>=6||(!equipmentClass(id)||equipmentClass(id)===classId);
export const SLOT_NAMES=['Оружие','Доп. оружие / щит','Шлем','Нагрудник','Штаны','Обувь'];
export function createInventory(){return Array(18).fill(null)}
export function addItem(slots,id,count=1){const same=slots.findIndex((s,i)=>i>=6&&s?.id===id);const index=same>=0?same:slots.findIndex((s,i)=>i>=6&&!s);if(index<0)return false;if(slots[index])slots[index].count+=count;else slots[index]={id,count};return true}
export function countItem(slots,id){return slots.reduce((n,s)=>n+(s?.id===id?s.count:0),0)}
export function removeItem(slots,id,count=1){if(countItem(slots,id)<count)return false;for(let i=0;i<slots.length&&count;i++){if(slots[i]?.id!==id)continue;const take=Math.min(count,slots[i].count);slots[i].count-=take;count-=take;if(!slots[i].count)slots[i]=null}return true}
export function moveItem(slots,from,to){if(!Number.isInteger(from)||!Number.isInteger(to)||from<0||to<0||from>=18||to>=18||from===to||!slots[from])return false;const fits=(item,index)=>!item||index>=6||ITEMS[item.id]?.slot===index;if(!fits(slots[from],to)||!fits(slots[to],from))return false;if(slots[to]?.id===slots[from].id&&to>=6){slots[to].count+=slots[from].count;slots[from]=null}else [slots[from],slots[to]]=[slots[to],slots[from]];return true}
export function itemIcon(id){if(ITEMS[id]?.weaponClass)return '<span class="fine-item">'+itemIcon(ITEMS[id].weaponClass)+'</span>';if(ITEMS[id]?.atlas)return '<span class="item-art" style="background-position:'+ITEMS[id].atlas+'"></span>'; if(ITEMS[id]?.slot===2)return '<svg viewBox="0 0 64 64" width="48" height="48"><path d="M12 55V28Q12 5 32 5Q52 5 52 28V55L42 49V30Q32 18 22 30V49Z" fill="'+ITEMS[id].color+'" stroke="#d4c5a2" stroke-width="2"/><path d="M16 21H48M16 26H48M16 32H22M42 32H48" stroke="#39353c" stroke-width="2"/></svg>';const shapes={shield:'<path d="M10 8H54V31Q51 49 32 60Q13 49 10 31Z" fill="#8c6543" stroke="#b4babe" stroke-width="4"/><path d="M32 10V55M13 28H51" stroke="#b4babe" stroke-width="3"/>',sword:'<path d="M27 4L34 4L33 40L26 40Z" fill="#c5d5dd"/><path d="M18 40H41M30 42V57" stroke="#bb9858" stroke-width="5"/>',bow:'<path d="M19 6Q57 32 19 58" fill="none" stroke="#b58c50" stroke-width="5"/><path d="M19 6V58M8 32H48L41 27M48 32L41 37" fill="none" stroke="#e1d5ae" stroke-width="2"/>',mage:'<path d="M30 22V58" stroke="#98724a" stroke-width="6"/><path d="M30 4L40 17L30 29L20 17Z" fill="#ff9952"/>',arrow:'<path d="M15 52L46 12M46 12L34 17M46 12L44 25M15 52L13 40M15 52L27 49" stroke="#dbd0a9" stroke-width="3" fill="none"/>',carcass:'<ellipse cx="31" cy="33" rx="17" ry="12" fill="#bc827b"/><ellipse cx="46" cy="24" rx="8" ry="7" fill="#c89c88"/><path d="M43 19L38 7M49 18L49 6M19 37L11 48M34 41L39 50" stroke="#c89c88" stroke-width="6"/>',fang:'<path d="M20 8Q48 6 42 29Q36 48 15 57Q30 34 20 8" fill="#e8dfbf"/><path d="M20 8Q32 18 44 16" stroke="#9e947d" fill="none"/>'};const extra={3:'M8 12L20 6L26 16H38L44 6L56 12L50 29L44 25V57H20V25L14 29Z',4:'M16 7H48L51 57H35L32 30L29 57H13Z',5:'M14 8H30V39L34 46V57H5V47L14 39ZM39 8H55V42L61 48V57H38Z'};const special=id==='shield_fine'?shapes.shield:id==='quiver'?'<path d="M19 18L40 21L39 56H17Z" fill="#95613d"/><path d="M22 28L27 3M31 29L39 4M38 30L49 10" stroke="#d6d8b7" stroke-width="3"/>':['grimoire','witch_relic'].includes(id)?'<path d="M10 9L48 6L54 53L16 57Z" fill="'+ITEMS[id].color+'" stroke="#d4c5a2" stroke-width="3"/><path d="M25 22L40 33L29 44L24 30Z" fill="#e4ecc5"/>':extra[ITEMS[id]?.slot]?'<path d="'+extra[ITEMS[id].slot]+'" fill="'+ITEMS[id].color+'" stroke="#d4c5a2" stroke-width="2"/>':'';return '<svg viewBox="0 0 64 64" width="48" height="48" aria-hidden="true">'+(special||shapes[id]||'')+'</svg>'}
